const r = await fetch("https://musicbrainz.org/ws/2/release/7222dfa2-2516-4ed3-98cd-91001242797e?inc=recordings&fmt=json", {
  headers: { "User-Agent": "sfa-extractor/0.1 (personal use script)" }
});
const data = await r.json();
console.log("Title:", data.title);
console.log("Artist:", data["artist-credit"]?.map(a => a.name).join(", "));
console.log("Date:", data.date);
for (const medium of data.media) {
  console.log(`\nMedium ${medium.position} (${medium.format}), ${medium["track-count"]} tracks:`);
  for (const t of medium.tracks) {
    console.log(`  ${t.position}. ${t.title} (${t.length ? Math.round(t.length/1000) + "s" : "?"})`);
  }
}
